onsprinzip:</b> Im Auszug erscheinen nur abgeschlossene Fahrten. Korrekturen abgeschlossener Datensätze werden im System mit Korrekturgrund, Zeitstempel und Vor-/Nachzustand protokolliert. Die steuerliche Anerkennung setzt eine tatsächliche, vollständige und zeitnahe Führung voraus.</div><table class="tbl"><thead><tr><th>Datum/Zeit</th><th>Fahrzeug</th><th>Art</th><th>Start</th><th>Ziel</th><th>Reisezweck / Geschäftspartner</th><th>Km Anfang</th><th>Km Ende</th><th>km</th><th>Umweg</th><th>Prüfsumme</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h(de_date($r['trip_date']))?></b><br><?=h(substr((string)($r['start_time']??''),0,5))?>–<?=h(substr((string)($r['end_time']??''),0,5))?></td><td><?=h($r['vehicle_label']??'')?> <br><?=h($r['license_plate']??'')?></td><td><?=h(['business'=>'geschäftlich','private'=>'privat','commute'=>'Wohnung/Betrieb'][$r['trip_type']]??$r['trip_type'])?></td><td><?=h($r['start_address'])?></td><td><?=h($r['destination_address'])?></td><td><?=h($r['purpose']??'')?> <br><b><?=h($r['business_partner']??'')?></b></td><td><?=number_format((float)$r['start_odometer'],1,',','.')?></td><td><?=number_format((float)$r['end_odometer'],1,',','.')?></td><td><b><?=number_format((float)$r['distance_km'],1,',','.')?></b></td><td><?=h($r['detour_reason']??'')?></td><td class="hash"><?=h(substr((string)($r['row_hash']??''),0,18))?>…</td></tr><?php endforeach;?></tbody></table><footer class="foot">Interne Aufzeichnung Räucherhaken24 · Exporthash <?=h($hash)?> · Die Originaldaten und das Änderungsprotokoll verbleiben im Orgaboard.</footer></main></body></html>